/* TITLE_OVERLAY_JS_PATCH START */
(function () {
  function createOverlay() {
    let wrap = document.getElementById("title_overlay_fixed");
    if (!wrap) {
      wrap = document.createElement("div");
      wrap.id = "title_overlay_fixed";

      Object.assign(wrap.style, {
        position: "fixed",
        left: "6px",
        top: "90px",
        width: "150px",
        height: "70px",
        zIndex: "2147483647",
        pointerEvents: "none",
        display: "block"
      });

      const bg = document.createElement("div");
      Object.assign(bg.style, {
        position: "absolute",
        left: "0",
        top: "0",
        width: "100%",
        height: "100%",
        background: "#b8e676",
        borderRadius: "8px"
      });
      wrap.appendChild(bg);

      const img = document.createElement("img");
      img.src = "data:image/png;base64,";
      Object.assign(img.style, {
        position: "absolute",
        left: "6px",
        top: "30px",
        width: "138px",
        height: "auto"
      });
      wrap.appendChild(img);

      document.body.appendChild(wrap);
    }
  }

  function ensure() {
    if (document.body) createOverlay();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", ensure);
  } else {
    ensure();
  }

  window.addEventListener("load", ensure);
  window.addEventListener("resize", ensure);
  window.addEventListener("luna:ready", ensure);
  window.addEventListener("luna:initialized", ensure);

  setInterval(ensure, 500);
})();
/* TITLE_OVERLAY_JS_PATCH END */
